function compute(state) {
  var x = state.x, w0 = state.w, i = x.length, k = w0.length, s = Math.max(1, Math.round(state.s));
  var w = state.flip ? w0.slice().reverse() : w0.slice();
  var p = state.mode === 'full' ? k - 1 : state.mode === 'same' ? Math.floor(k / 2) : 0;
  var xp = [], isPad = [];
  for (var a = 0; a < p; a++) { xp.push(0); isPad.push(1); }
  x.forEach(function (v) { xp.push(v); isPad.push(0); });
  for (var b = 0; b < p; b++) { xp.push(0); isPad.push(1); }
  var o = Math.max(0, Math.floor((i + 2 * p - k) / s) + 1);
  var y = [];
  for (var j = 0; j < o; j++) { var acc = 0; for (var m = 0; m < k; m++) acc += w[m] * xp[j * s + m]; y.push(acc); }
  var jj = o > 0 ? Math.min(Math.max(1, Math.round(state.j)), o) - 1 : -1;
  var rows = [];
  if (jj >= 0) for (var q = 0; q < k; q++) rows.push(['w' + (q + 1) + (state.flip ? ' (flipped)' : ''), w[q], 'x̃' + (jj * s + q + 1) + (isPad[jj * s + q] ? ' (pad)' : ''), xp[jj * s + q], w[q] * xp[jj * s + q]]);
  var values = { o: o, o_formula: Math.floor((i + 2 * p - k) / s) + 1, count_y: y.length, p: p, padded_len: i + 2 * p, j: jj };
  if (jj >= 0) { values.y_j = y[jj]; rows.push(['Σ', '', '', '', y[jj]]); }
  return {
    values: values,
    series: { y: y, xp: xp, is_pad: isPad, w_used: w, y_labels: y.map(function (_, t) { return 'y' + (t + 1); }) },
    tables: { terms: { cols: ['Weight', 'value', 'Padded input', 'value', 'Product'], rows: rows } }
  };
}

visuals.draw:
function draw(svg, state, out, h) {
  var xp = out.series.xp, pad = out.series.is_pad, y = out.series.y, w = out.series.w_used;
  var k = w.length, s = Math.max(1, Math.round(state.s)), j = out.values.j;
  var n = Math.max(xp.length, 1), cw = Math.min(46, (h.W - 40) / n), x0 = (h.W - cw * n) / 2;
  var Y1 = 34, Y2 = 118, Y3 = 210, ch = 34;
  h.text(x0, Y1 - 10, 'padded input x̃', { class: 'axis-title' });
  var lo = j >= 0 ? j * s : -1, hi = j >= 0 ? j * s + k : -1;
  xp.forEach(function (v, t) {
    var inWin = t >= lo && t < hi;
    h.el('rect', { x: x0 + t * cw + 1, y: Y1, width: cw - 2, height: ch, rx: 4, fill: inWin ? 'rgb(36,89,214)' : 'none', 'fill-opacity': inWin ? 0.18 : 0, stroke: inWin ? 'rgb(36,89,214)' : 'var(--axis)', 'stroke-dasharray': pad[t] ? '4 3' : null, 'stroke-width': inWin ? 2 : 1 }, svg);
    h.text(x0 + t * cw + cw / 2, Y1 + ch / 2 + 4, h.fmt(v, 1), { class: 'vlabel', 'text-anchor': 'middle' });
  });
  if (j < 0) { h.text(h.W / 2, Y2 + 20, 'No valid position: the kernel (k = ' + k + ') is longer than the padded input.', { 'text-anchor': 'middle', style: 'fill: var(--bad)' }); return; }
  h.text(x0, Y2 - 10, 'kernel w at output j = ' + (j + 1), { class: 'axis-title' });
  w.forEach(function (v, m) {
    var cx = x0 + (lo + m) * cw;
    h.el('rect', { x: cx + 1, y: Y2, width: cw - 2, height: ch, rx: 4, fill: 'rgb(214,104,26)', 'fill-opacity': 0.2, stroke: 'rgb(214,104,26)' }, svg);
    h.text(cx + cw / 2, Y2 + ch / 2 + 4, h.fmt(v, 1), { class: 'vlabel', 'text-anchor': 'middle' });
    h.el('line', { x1: cx + cw / 2, y1: Y1 + ch, x2: cx + cw / 2, y2: Y2, stroke: 'var(--axis)', 'stroke-dasharray': '2 2' }, svg);
  });
  var on = y.length, ow = Math.min(46, (h.W - 40) / Math.max(on, 1)), ox = (h.W - ow * on) / 2;
  h.text(ox, Y3 - 10, 'output y (length o = ' + on + ')', { class: 'axis-title' });
  y.forEach(function (v, t) {
    var act = t === j;
    h.el('rect', { x: ox + t * ow + 1, y: Y3, width: ow - 2, height: ch, rx: 4, fill: act ? 'rgb(31,157,106)' : 'none', 'fill-opacity': act ? 0.22 : 0, stroke: act ? 'rgb(31,157,106)' : 'var(--axis)', 'stroke-width': act ? 2 : 1 }, svg);
    h.text(ox + t * ow + ow / 2, Y3 + ch / 2 + 4, h.fmt(v, 1), { class: 'vlabel', 'text-anchor': 'middle' });
  });
  var midK = x0 + (lo + k / 2) * cw;
  h.el('line', { x1: midK, y1: Y2 + ch, x2: ox + j * ow + ow / 2, y2: Y3, stroke: 'rgb(31,157,106)', 'stroke-width': 2 }, svg);
  h.text(x0 + (lo + k) * cw + 10, Y2 + ch / 2 + 4, '→ Σ products = ' + h.fmt(y[j], 2), { class: 'vlabel' });
}
